const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
export function initialState(){return {c:0,r:0,moves:0,hint:false,msg:'Move the token to the gold goal square.'};}
const won=s=>s.c===2&&s.r===2;
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;const s={...state};
if(won(s)){s.msg='You already won in '+s.moves+' moves. Press Reset to play again.';return s;}
if(a==='hint'){s.hint=true;s.msg=s.c<2?'Hint: moving Right brings you one step closer.':'Hint: moving Up brings you one step closer.';return s;}
const d=D[a];if(!d)return s;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board, so nothing happened.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=false;
s.msg=won(s)?'You reached the goal in '+s.moves+' moves! The shortest route is 4 moves.':'Moved '+a+'. Keep going.';
return s;}
export function evaluate({state}){
const s=state;const x=(s.c-1)*1.1,z=(1-s.r)*1.1;
const q=s.c<2?[0,0,-0.7071068,0.7071068]:[-0.7071068,0,0,0.7071068];
const w=won(s);
return {nodes:{token:{position:[x,0.35,z]},hint:{position:[x,0.35,z],quaternion:q,visible:s.hint&&!w}},
readouts:{moves:s.moves,dist:(2-s.c)+(2-s.r)},
goal:{status:w?'won':'playing',message:s.msg}};}
